#include <iostream>
#include <memory>
struct Node : std::enable_shared_from_this<Node> {
    void f() {
        auto self = shared_from_this();   // 安全地获取指向自身的 shared_ptr（不造第二个控制块）
        std::cout << self.use_count() << '\n';
    }
    ~Node(){ std::cout << "~Node\n"; }
};
int main() {
    auto p = std::make_shared<Node>();
    p->f();                                // 已交由 shared_ptr 管理，调用合法
}
